private PetAppResponse<String> doUpload(String url, MultipartFile file) {
        try {
            HttpHeaders headers = buildMultipartHeaders();
            LinkedMultiValueMap<String, Object> body = new LinkedMultiValueMap<>();

            ByteArrayResource resource = toResource(file);
            body.add("file", resource);

            HttpEntity<LinkedMultiValueMap<String, Object>> requestEntity = new HttpEntity<>(body, headers);
            return restTemplate.exchange(url, HttpMethod.POST, requestEntity,
                    new ParameterizedTypeReference<PetAppResponse<String>>() {}).getBody();
        } catch (IOException e) {
            throw new EclipseRuntimeException("读取上传文件失败", e, "SYS_ERROR");
        }
    }

private ByteArrayResource toResource(MultipartFile file) throws IOException {
        String encodedName = encodeFilename(file.getOriginalFilename());
        return new ByteArrayResource(file.getBytes()) {
            @Override
            public String getFilename() {
                return encodedName;
            }
        };
    }

private String encodeFilename(String filename) {
        if (filename == null) {
            return null;
        }
        try {
            return URLEncoder.encode(filename, "UTF-8");
        } catch (UnsupportedEncodingException e) {
            // UTF-8 为 JDK 必备字符集, 理论不会进入此分支; 兜底原样返回
            return filename;
        }
    }
